type Row = Record<string, any>;
type Rule = { id: string; direction: "LONG" | "SHORT"; indicator: string; period: number; operator: string; rightKind: "indicator" | "constant"; rightIndicator: string; rightPeriod: number; value: number };
const isoInput = (ms: number) => new Date(ms).toISOString().slice(0, 16);
const elapsed = (startedAt?: string | null, completedAt?: string | null) => { if (!startedAt) return "—"; const ms = new Date(completedAt ?? Date.now()).getTime() - new Date(startedAt).getTime(), seconds = Math.max(0, Math.floor(ms / 1000)); return `${Math.floor(seconds / 60)}m ${seconds % 60}s`; };
