function toCondition(rule: Rule, timeframe: string) {
  const left = { type: "indicator", indicator: rule.indicator, parameters: { period: Number(rule.period) }, timeframe };
  const right = rule.rightKind === "indicator" ? { type: "indicator", indicator: rule.rightIndicator, parameters: { period: Number(rule.rightPeriod) }, timeframe } : { type: "constant", value: Number(rule.value) };
  return { left, operator: rule.operator, right };
}
